module.exports = /*#__PURE__*/JSON.parse('{"data":{"wp":{"optionPage":{"zaynichInjectionSection":{"zaynichSection":" <section className=\\"zaynich-safety\\" id=\\"zaynichSafety\\" aria-labelledby=\\"zaynichSafetyTitle\\">\\r\\n      <div className=\\"zaynich-safety__card\\">\\r\\n        <h2 id=\\"zaynichSafetyTitle\\">ZAYNICH™ (cefepime and zidebactam) for Injection</h2>\\r\\n\\r\\n        <h3>Indication and Usage</h3>\\r\\n\\r\\n        <div className=\\"safety-block\\">\\r\\n          <h4>Complicated Urinary Tract Infections, Including Pyelonephritis</h4>\\r\\n          <ul>\\r\\n            <li>\\r\\n              ZAYNICH™ is indicated for the treatment of adult patients with complicated urinary tract\\r\\n              infections (cUTI), including pyelonephritis caused by the following susceptible microorganisms:{\\" \\"}\\r\\n              <em>Escherichia coli</em>, <em>Klebsiella pneumoniae</em>, <em>Proteus mirabilis</em>,{\\" \\"}\\r\\n              <em>Enterobacter cloacae</em> complex, and <em>Pseudomonas aeruginosa</em>.\\r\\n            </li>\\r\\n          </ul>\\r\\n        </div>\\r\\n\\r\\n        <div className=\\"safety-block\\">\\r\\n          <h4>Usage to Reduce Development of Drug-Resistant Bacteria</h4>\\r\\n          <ul>\\r\\n            <li>\\r\\n              To reduce the development of drug-resistant bacteria and maintain the effectiveness of ZAYNICH™\\r\\n              and other antibacterial drugs, ZAYNICH™ should be used only to treat or prevent infections that\\r\\n              are proven or strongly suspected to be caused by susceptible bacteria.\\r\\n            </li>\\r\\n          </ul>\\r\\n        </div>\\r\\n\\r\\n        <div className=\\"safety-block safety-block--inline\\">\\r\\n          <p>\\r\\n            <strong>Important Safety Information — Contraindications:</strong> ZAYNICH™ is contraindicated in\\r\\n            patients with a known history of serious hypersensitivity to the components of ZAYNICH™ (cefepime\\r\\n            and zidebactam) or other beta-lactam antibacterial drugs.\\r\\n          </p>\\r\\n        </div>\\r\\n\\r\\n        <div className=\\"safety-block\\">\\r\\n          <h3>Warnings and Precautions</h3>\\r\\n          <ul>\\r\\n            <li>\\r\\n              <strong>Hypersensitivity Reactions:</strong> Serious hypersensitivity reactions, including\\r\\n              anaphylaxis, have been reported in patients treated with ZAYNICH™. Serious and occasionally fatal\\r\\n              hypersensitivity reactions and serious skin reactions have been reported in patients receiving\\r\\n              beta-lactam antibacterial drugs. Before therapy with ZAYNICH™ is instituted, carefully inquire\\r\\n              about previous hypersensitivity reactions to cefepime, cephalosporins, penicillins, or other\\r\\n              beta-lactams because cross-hypersensitivity among beta-lactam antibacterial drugs has been\\r\\n              reported. If an allergic reaction to ZAYNICH™ occurs, discontinue the drug and institute\\r\\n              appropriate supportive measures.\\r\\n            </li>\\r\\n\\r\\n            <li>\\r\\n              <strong>Neurotoxicity:</strong> Neurotoxicity has been reported during treatment with cefepime, a\\r\\n              component of ZAYNICH™, including life-threatening or fatal occurrences of encephalopathy,\\r\\n              aphasia, myoclonus, seizures, and nonconvulsive status epilepticus. Most cases occurred in\\r\\n              patients with renal impairment who did not receive appropriate dosage adjustment. If\\r\\n              neurotoxicity associated with ZAYNICH™ therapy occurs, discontinue ZAYNICH™ and institute\\r\\n              appropriate supportive measures.\\r\\n            </li>\\r\\n\\r\\n            <li>\\r\\n              <strong>Clostridioides difficile-Associated Diarrhea (CDAD):</strong> CDAD has been reported with\\r\\n              the use of nearly all antibacterial agents, including ZAYNICH™, and may range in severity from\\r\\n              mild diarrhea to fatal colitis. Careful medical history is necessary because CDAD has been\\r\\n              reported to occur over two months after the administration of antibacterial agents. If CDAD is\\r\\n              suspected or confirmed, ongoing antibacterial drug use not directed against <em>C. difficile</em>{\\" \\"}\\r\\n              may need to be discontinued.\\r\\n            </li>\\r\\n\\r\\n            <li>\\r\\n              <strong>Positive Direct Coombs\' Tests:</strong> Positive direct Coombs\' tests with or without hemolysis have been reported during treatment with cefepime, a component of ZAYNICH™. In patients who develop hemolytic anemia, discontinue the drug and institute appropriate therapy.\\r\\n            </li>\\r\\n            <li>\\r\\n              <strong>Prolonged Prothrombin Time:</strong> Decrease in prothrombin activity has been reported for many cephalosporins including cefepime, a component of ZAYNICH™. Those at risk include patients with renal or hepatic impairment or poor nutritional state, as well as patients receiving a protracted course of antimicrobial therapy. Prothrombin time should be monitored in patients at risk, and exogenous vitamin K should be administered as indicated.\\r\\n            </li>\\r\\n\\r\\n            <li>\\r\\n              <strong>Development of Drug-Resistant Bacteria:</strong> Prescribing ZAYNICH™ in the absence of a proven or strongly suspected bacterial infection or a prophylactic indication is unlikely to provide benefit to the patient and increases the risk of the development of drug-resistant bacteria.\\r\\n            </li>\\r\\n\\r\\n            <li>\\r\\n              <strong>Interactions with Urine Glucose Testing: </strong> The administration of cefepime, a component of ZAYNICH™, may result in a false-positive reaction for glucose in the urine when using some methods (e.g., Clinitest™ tablets). It is recommended that glucose tests based on enzymatic glucose oxidase reactions be used.\\r\\n            </li>\\r\\n\\r\\n            <li>\\r\\n              <strong>Interactions with Urine Glucose Testing: </strong> The administration of cefepime, a component of ZAYNICH™, may result in a false-positive reaction for glucose in the urine when using some methods (e.g., Clinitest™ tablets). It is recommended that glucose tests based on enzymatic glucose oxidase reactions be used.\\r\\n            </li>\\r\\n\\r\\n\\r\\n          </ul>\\r\\n           <div className=\\"safety-block safety-block--inline\\">\\r\\n          <p>\\r\\n            <strong>ADVERSE REACTIONS</strong> The most common adverse reactions occurring in ≥2% of patients receiving ZAYNICH™ were diarrhea, hypertension, headache, and hypokalemia.\\r\\n          </p>\\r\\n        </div>\\r\\n        </div>\\r\\n      </div>\\r\\n    </section>"}}}}}');

